      "03213": {
        "id": "工項_公路局_植筋",
        "chapter_code": "03213",
        "規範源": "公路局",
        "章碼別名": [],
        "title": "工項 植筋（公路局）",
        "標單別名": [
          "植筋",
          "化學黏著錨筋",
          "化學黏著錨栓",
          "後置式鋼筋",
          "植筋拉拔試驗",
          "施工前拉拔試驗",
          "施工後拉拔試驗"
        ],
        "試驗頻率卡": "",
        "停留點": [
          {
            "階段": "施工前",
            "查驗項目": "化學黏著藥劑 ASTM E1512、ICC-ES AC308 認證、腐蝕測試報告、原廠出廠/進口文件送審",
            "停留點": "H"
          },
          {
            "階段": "施工前",
            "查驗項目": "辦理施工前拉拔試驗 30 天前提送施工計畫及施工圖說",
            "停留點": "H"
          },
          {
            "階段": "施工前",
            "查驗項目": "油壓千斤頂及手動幫浦提供 TAF 認可實驗單位 6 個月內校正報告",
            "停留點": "H"
          },
          {
            "階段": "放樣",
            "查驗項目": "鑽孔前以鋼筋探測器確認既有鋼筋位置並留存掃描紀錄",
            "停留點": "H"
          },
          {
            "階段": "鑽孔",
            "查驗項目": "鑽孔直徑、深度、角度依 ICC 報告及核定施工計畫；遇既有鋼筋不得鑽斷",
            "停留點": "H"
          },
          {
            "階段": "注膠植入",
            "查驗項目": "注膠由孔底退至孔口，至少六分滿，植入至底部且可目視藥劑外溢",
            "停留點": "H"
          },
          {
            "階段": "固化",
            "查驗項目": "植筋完成後靜置避免擾動，超過藥劑膠凝時間始得負載或後續施工",
            "停留點": "H"
          },
          {
            "階段": "試驗",
            "查驗項目": "施工前拉拔試驗成果核可後始得施工；施工後拉拔試驗依頻率辦理",
            "停留點": "H"
          }
        ],
        "材料頻率": [
          {
            "項目": "藥劑認證",
            "方法": "ASTM E1512、ICC-ES AC308",
            "頻率": "使用前送審",
            "判定": "握裹性、潛變、耐震、潮濕環境與腐蝕測試報告核可",
            "備註": ""
          },
          {
            "項目": "鋼筋/螺栓材料",
            "方法": "03210、ASTM A449 Type 1",
            "頻率": "進場審查",
            "判定": "錨筋規格、降伏強度、埋設深度符設計圖；螺栓依規定熱浸鍍鋅",
            "備註": ""
          },
          {
            "項目": "施工前拉拔試驗",
            "方法": "ASTM E488/E488M 張力受限",
            "頻率": "依設計所需植筋規格及不同混凝土強度，各測試 1 組（3 支）",
            "判定": "同組螺栓握裹力均不發生握裹破壞，混凝土表面不得裂縫或明顯損壞",
            "備註": ""
          },
          {
            "項目": "施工後拉拔試驗",
            "方法": "參考 ASTM E488/E488M",
            "頻率": "橋梁工程每 100 支取 1 支，餘數不足 100 支取 1 支；其他結構每 300 支取 1 支，餘數不足 300 支取 1 支",
            "判定": "達設計圖標註設計拉力",
            "備註": ""
          },
          {
            "項目": "施工後拉拔失敗複驗",
            "方法": "同上",
            "頻率": "同批改取 25% 測試；若 25% 有任一不合格，該批全部測試",
            "判定": "失敗植筋由承商無償補設；再不合格須補設並重新檢驗",
            "備註": ""
          },
          {
            "項目": "累積全部測試",
            "方法": "同上",
            "頻率": "累積發生 3 次全部測試情形",
            "判定": "承商應更換化學黏著劑廠牌",
            "備註": ""
          }
        ],
        "查核紅線": [
          "[[00_公路局施工說明書_工項卡索引|公路局施工說明書工項卡索引]]",
          "[[112_03213_植筋|公路局 03213 原文卡]]",
          "[[工項_鋼筋|工項 鋼筋]]",
          "[[工項_無收縮水泥砂漿|工項 無收縮水泥砂漿]]"
        ],
        "status": "verified"
      },
